package com.ultimatestattracker;

public enum StatCategory
{
	ITEMS,
	SHOPS,
	MOVEMENT,
	FISHING,
	MINING,
	WOODCUTTING,
	GATHERING,
	FARMING,
	MISC,
	PRAYER,
	FIREMAKING,
	FOOD_AND_HEALING,
	THIEVING,
	AGILITY,
	HERBLORE,
	RUNECRAFT,
	CRAFTING,
	FLETCHING,
	HUNTER,
	SMITHING,
	COMBAT;

	public String getDisplayName()
	{
		switch (this)
		{
			case ITEMS:
				return "Items";
			case SHOPS:
				return "Shops";
			case MOVEMENT:
				return "Movement";
			case FOOD_AND_HEALING:
				return "Food & Healing";
			case GATHERING:
				return "Gathering";
			default:
				String name = name();
				return name.charAt(0) + name.substring(1).toLowerCase().replace('_', ' ');
		}
	}
}

package com.ultimatestattracker;

import net.runelite.client.game.SkillIconManager;

import javax.swing.*;
import java.awt.*;
import java.util.EnumMap;
import java.util.Map;

class StatCategoryFilterBar extends JPanel
{
	private static final int COLUMNS = 7;
	private static final int BUTTON_SIZE = 24;
	private static final int GAP = 2;

	private final Map<StatCategory, JToggleButton> buttons = new EnumMap<>(StatCategory.class);
	private StatCategory selected;

	StatCategoryFilterBar(SkillIconManager skillIconManager, Runnable onFilterChanged)
	{
		int rows = (StatCategory.values().length + COLUMNS - 1) / COLUMNS;
		int height = rows * (BUTTON_SIZE + GAP) + GAP;

		setLayout(new GridLayout(rows, COLUMNS, GAP, GAP));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setPreferredSize(new Dimension(Short.MAX_VALUE, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setMinimumSize(new Dimension(0, height));

		for (StatCategory category : StatCategory.values())
		{
			JToggleButton button = new JToggleButton(new ImageIcon(StatCategoryIcons.getIcon(category, skillIconManager)));
			button.setToolTipText(category.getDisplayName());
			button.setPreferredSize(new Dimension(BUTTON_SIZE, BUTTON_SIZE));
			button.setFocusable(false);
			button.setMargin(new Insets(1, 1, 1, 1));

			button.addActionListener(e ->
			{
				if (button.isSelected())
				{
					if (selected != null && selected != category)
					{
						buttons.get(selected).setSelected(false);
					}
					selected = category;
				}
				else
				{
					selected = null;
				}
				onFilterChanged.run();
			});

			buttons.put(category, button);
			add(button);
		}
	}

	StatCategory getSelectedCategory()
	{
		return selected;
	}
}

package com.ultimatestattracker;

import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.client.util.ImageUtil;

final class StatCategoryIcons
{
	private static final int ICON_SIZE = 20;

	private static BufferedImage unknownIcon;
	private static BufferedImage coinsIcon;
	private static BufferedImage transportIcon;
	private static BufferedImage flaxIcon;
	private static BufferedImage bankNoteIcon;

	private StatCategoryIcons()
	{
	}

	static BufferedImage getIcon(StatCategory category, SkillIconManager skillIconManager)
	{
		Skill skill = skillFor(category);
		if (skill != null)
		{
			return skillIconManager.getSkillImage(skill, true);
		}

		switch (category)
		{
			case SHOPS:
				return getCoinsIcon();

			case MOVEMENT:
				return getTransportIcon();

			case GATHERING:
				return getFlaxIcon();

			case ITEMS:
				return getBankNoteIcon();

			default:
				return getUnknownIcon();
		}
	}

	private static BufferedImage getCoinsIcon()
	{
		if (coinsIcon == null)
		{
			coinsIcon = ImageUtil.loadImageResource(
					StatCategoryIcons.class,
					"Coins_10000.png"
			);
		}
		return coinsIcon;
	}

	private static BufferedImage getTransportIcon()
	{
		if (transportIcon == null)
		{
			transportIcon = ImageUtil.loadImageResource(
					StatCategoryIcons.class,
					"Transportation_icon.png"
			);
		}
		return transportIcon;
	}

	private static BufferedImage getFlaxIcon()
	{
		if (flaxIcon == null)
		{
			flaxIcon = ImageUtil.loadImageResource(
					StatCategoryIcons.class,
					"Flax.png"
			);
		}
		return flaxIcon;
	}

	private static BufferedImage getBankNoteIcon()
	{
		if (bankNoteIcon == null)
		{
			bankNoteIcon = ImageUtil.loadImageResource(
					StatCategoryIcons.class,
					"Bank_note.png"
			);
		}
		return bankNoteIcon;
	}

	private static Skill skillFor(StatCategory category)
	{
		switch (category)
		{
			case FISHING:
				return Skill.FISHING;
			case MINING:
				return Skill.MINING;
			case WOODCUTTING:
				return Skill.WOODCUTTING;
			case FARMING:
				return Skill.FARMING;
			case PRAYER:
				return Skill.PRAYER;
			case FIREMAKING:
				return Skill.FIREMAKING;
			case FOOD_AND_HEALING:
				return Skill.HITPOINTS;
			case THIEVING:
				return Skill.THIEVING;
			case AGILITY:
				return Skill.AGILITY;
			case HERBLORE:
				return Skill.HERBLORE;
			case RUNECRAFT:
				return Skill.RUNECRAFT;
			case CRAFTING:
				return Skill.CRAFTING;
			case FLETCHING:
				return Skill.FLETCHING;
			case HUNTER:
				return Skill.HUNTER;
			case SMITHING:
				return Skill.SMITHING;
			case COMBAT:
				return Skill.ATTACK;
			default:
				return null;
		}
	}

	private static BufferedImage getUnknownIcon()
	{
		if (unknownIcon == null)
		{
			BufferedImage img = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = img.createGraphics();
			g.setColor(new Color(180, 180, 180));
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
			g.drawString("?", 5, 15);
			g.dispose();
			unknownIcon = img;
		}
		return unknownIcon;
	}
}

package com.ultimatestattracker;

public final class StatKey
{
	private final String value;
	private final StatCategory category;

	public StatKey(String value, StatCategory category, String displayString)
	{
		this.value = value;
		this.category = category;
		this.displayString = displayString;
	}

	public String getValue()
	{
		return value;
	}
	public StatCategory getCategory()
	{
		return category;
	}
	public String displayString;
}

