package com.ultimatestattracker;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import java.util.Arrays;
import java.util.Objects;

import static com.ultimatestattracker.StatKeys.ALL_KEYS;

@Slf4j
public class StatStore {
    private static final String CONFIG_GROUP = "ultimatestattracker";
    private final MilestoneManager milestoneManager;
    private ConfigManager cfg;
    private UltimateStatTrackerPlugin plugin;

    public StatStore(ConfigManager cfg, UltimateStatTrackerPlugin plugin, MilestoneManager milestoneManager){
        this.cfg = cfg;
        this.milestoneManager = milestoneManager;
    }

    public void storeStat(String key, int value){
        //log.debug("Previous stat value for {}: {}", key, getStat(key));
        cfg.setRSProfileConfiguration(CONFIG_GROUP, key, value);
    }

    public int getStat(String key)
    {
        Integer value = cfg.getRSProfileConfiguration(CONFIG_GROUP, key, Integer.class);
        return value == null ? 0 : value;
    }

    public void incrementStat(String key)
    {
        log.debug("increment called");
        incrementStatBy(key,1);
    }

    public void incrementStatBy(String key, int value)
    {
        //log.debug("increment by called");
        int current=getStat(key);
        if(current>Integer.MAX_VALUE-value){ //overflow protection
            storeStat(key,Integer.MAX_VALUE);
            return;
        }
        StatKey statkey = Arrays.stream(ALL_KEYS)
                .filter(k -> Objects.equals(k.getValue(), key))
                .findFirst()
                .orElse(null);

        if (statkey != null & milestoneManager.Enabled && milestoneManager.MilestoneReached(current + value, current)) {
            milestoneManager.SendMilestoneMessage(current + value,statkey);
        }
        storeStat(key,current+value);

    }

    public void setStat(String key, int value){
        storeStat(key, value);
    }

    public void setStatTrackingDate(String key,String value){
        log.debug("setting stat tracking date for key {} to value {}", key, value);
        String dateKey = key + "date";
        cfg.setRSProfileConfiguration(CONFIG_GROUP, dateKey, value);
    }

    public String getStatTrackingDate(String key)
    {
        String dateKey = key + "date";
        String value = cfg.getRSProfileConfiguration(CONFIG_GROUP, dateKey);
        if (value == null || value.isEmpty())
        {
            return "0";
        }
        return value;
    }
}

