package com.ultimatestattracker;

import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.stream.Collectors;

import net.runelite.client.game.SkillIconManager;

import static com.ultimatestattracker.StatKeys.*;

public class UltimateStatTrackerPanel extends PluginPanel
{
    private final JPanel content = new JPanel();
    private final JTextField searchField = new JTextField();
    private final JComboBox<String> sortBox = new JComboBox<>(new String[]{"Alphabetical", "Numeric"});
    private StatStore statStore;
    private String filter = "";
    private static final Map<String, String> STAT_LABELS = new LinkedHashMap<>();
    private static final Color COLOR_DISABLED = new Color(100, 100, 100);
    private static final String PERFORMANCE_MODE_TOOLTIP = "Disabled in performance mode";


    private final StatCategoryFilterBar categoryFilterBar;

    private UltimateStatTrackerPlugin plugin;


    public UltimateStatTrackerPanel(UltimateStatTrackerPlugin plugin, SkillIconManager skillIconManager)
    {
        this.plugin = plugin;
        categoryFilterBar = new StatCategoryFilterBar(skillIconManager, this::rebuild);
        setLayout(new BorderLayout());

        JPanel topBar = new JPanel();
        topBar.setLayout(new BoxLayout(topBar, BoxLayout.Y_AXIS));

        searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
        searchField.setAlignmentX(Component.LEFT_ALIGNMENT);

        searchField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
        {
            private void update()
            {
                filter = searchField.getText().toLowerCase();
                rebuild();
            }

            @Override public void insertUpdate(javax.swing.event.DocumentEvent e) { update(); }
            @Override public void removeUpdate(javax.swing.event.DocumentEvent e) { update(); }
            @Override public void changedUpdate(javax.swing.event.DocumentEvent e) { update(); }
        });

        JButton refreshButton = new JButton("Refresh");
        refreshButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        refreshButton.addActionListener(e -> rebuild());

        JButton resetAllButton = new JButton("Reset All");
        resetAllButton.setAlignmentX(Component.LEFT_ALIGNMENT);

        resetAllButton.addActionListener(e ->
        {
            int result = JOptionPane.showConfirmDialog(
                    this,
                    "Reset ALL stats? This cannot be undone.",
                    "Confirm Reset All",
                    JOptionPane.YES_NO_OPTION,
                    JOptionPane.WARNING_MESSAGE
            );

            if (result == JOptionPane.YES_OPTION && statStore != null)
            {
                String formattedDate = java.time.Instant.ofEpochMilli(System.currentTimeMillis())
                        .atZone(java.time.ZoneId.systemDefault())
                        .format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd"));

                for (StatKey key : ALL_KEYS)
                {
                    statStore.setStat(key.getValue(), 0);
                    statStore.setStatTrackingDate(key.getValue(), formattedDate);
                }

                rebuild();
            }
        });

        sortBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
        sortBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        sortBox.addActionListener(e -> rebuild());

        JPanel buttonRow = new JPanel();
        buttonRow.setLayout(new BoxLayout(buttonRow, BoxLayout.X_AXIS));
        buttonRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        buttonRow.add(refreshButton);
        buttonRow.add(Box.createHorizontalGlue());
        buttonRow.add(resetAllButton);

        topBar.add(searchField);
        topBar.add(buttonRow);
        topBar.add(sortBox);
        topBar.add(categoryFilterBar);

        add(topBar, BorderLayout.NORTH);

        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(new Color(40, 35, 30));

        add(content, BorderLayout.CENTER);
    }

    public void setStatStore(StatStore store)
    {
        this.statStore = store;
        rebuild();
    }

    @Override
    public void onActivate()
    {
        rebuild();
    }

    private List<Map.Entry<String, String>> getSortedEntries()
    {
        String selected = (String) sortBox.getSelectedItem();

        var entries = Arrays.stream(ALL_KEYS).map(x -> Map.entry(x.getValue(), x.displayString)).collect(Collectors.toList());

        if ("Alphabetical".equals(selected))
        {
            entries.sort(Comparator.comparing(e -> e.getValue().toLowerCase()));
        }
        else if ("Numeric".equals(selected) && statStore != null)
        {
            entries.sort((a, b) -> Integer.compare(
                    statStore.getStat(b.getKey()),
                    statStore.getStat(a.getKey())
            ));
        }

        return entries;
    }

    public void rebuild()
    {
        content.removeAll();

        JLabel title = new JLabel("Ultimate Stat Tracker");
        title.setForeground(Color.ORANGE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(title);

        content.add(Box.createVerticalStrut(10));

        if (!plugin.loggedIn){
            JLabel notLoggedIn = new JLabel("Please log in to see your stats.");
            notLoggedIn.setForeground(Color.GRAY);
            notLoggedIn.setAlignmentX(Component.LEFT_ALIGNMENT);
            content.add(notLoggedIn);
            revalidate();
            repaint();
            return;
        }
        int hiddenStats = 0;
        if (statStore != null)
        {
            for (Map.Entry<String, String> entry : getSortedEntries())
            {
                String key = entry.getKey();
                String label = entry.getValue();

                if (!filter.isEmpty() && !label.toLowerCase().contains(filter))
                {
                    continue;
                }

                StatCategory activeCategory = categoryFilterBar.getSelectedCategory();
                if (activeCategory != null && StatKeys.KEY_TO_CATEGORY.get(key) != activeCategory)
                {
                    continue;
                }

                int value = statStore.getStat(key);

                if (plugin.isHideZeroStatsEnabled() && value == 0)
                {
                    hiddenStats++;
                    continue;
                }

                boolean notTracked = plugin.isPerformanceMode() && PERFORMANCE_MODE_DISABLED_KEYS.contains(key);

                JPanel row = new JPanel(new BorderLayout());
                row.setBackground(content.getBackground());
                row.setAlignmentX(Component.LEFT_ALIGNMENT);

                JPanel leftPanel = new JPanel();
                leftPanel.setLayout(new BoxLayout(leftPanel, BoxLayout.X_AXIS));
                leftPanel.setBackground(content.getBackground());

                JLabel left = new JLabel(label);
                left.setForeground(notTracked ? COLOR_DISABLED : Color.WHITE);

                JLabel info = new JLabel(" ⓘ");
                info.setForeground(notTracked ? COLOR_DISABLED : Color.GRAY);
                String date = statStore.getStatTrackingDate(key);
                if (notTracked)
                {
                    info.setToolTipText("Not tracked while Performance Mode is enabled.");
                }
                else
                {
                    info.setToolTipText(date != null ? "Tracking since: " + date : "No data");
                }

                leftPanel.add(left);
                leftPanel.add(info);

                String formatted;
                if (value == Integer.MAX_VALUE)
                {
                    formatted = "Lots!";
                }
                else
                {
                    formatted = formatStack(value);
                }

                JLabel right = new JLabel(formatted);

                if (notTracked)
                {
                    right.setForeground(COLOR_DISABLED);
                }
                else if (value == Integer.MAX_VALUE || formatted.contains("M"))
                {
                    right.setForeground(Color.GREEN);
                }
                else
                {
                    right.setForeground(Color.WHITE);
                }

                row.add(leftPanel, BorderLayout.WEST);
                row.add(right, BorderLayout.EAST);

                if (notTracked)
                {
                    row.setToolTipText(PERFORMANCE_MODE_TOOLTIP);
                    leftPanel.setToolTipText(PERFORMANCE_MODE_TOOLTIP);
                    left.setToolTipText(PERFORMANCE_MODE_TOOLTIP);
                    info.setToolTipText(PERFORMANCE_MODE_TOOLTIP);
                    right.setToolTipText(PERFORMANCE_MODE_TOOLTIP);
                }

                // ---------------- RIGHT CLICK MENU ----------------
                JPopupMenu menu = new JPopupMenu();
                JMenuItem resetItem = new JMenuItem("Reset stat");
                menu.add(resetItem);

                resetItem.addActionListener(e ->
                {
                    int result = JOptionPane.showConfirmDialog(
                            this,
                            "Reset \"" + label + "\"?",
                            "Confirm Reset",
                            JOptionPane.YES_NO_OPTION,
                            JOptionPane.WARNING_MESSAGE
                    );

                    if (result == JOptionPane.YES_OPTION)
                    {
                        statStore.setStat(key, 0);
                        String formattedDate = java.time.Instant.ofEpochMilli(System.currentTimeMillis())
                                .atZone(java.time.ZoneId.systemDefault())
                                .format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd"));
                        statStore.setStatTrackingDate(key,formattedDate);
                        rebuild();
                    }
                });

                row.addMouseListener(new java.awt.event.MouseAdapter()
                {
                    @Override
                    public void mousePressed(java.awt.event.MouseEvent e)
                    {
                        if (e.isPopupTrigger())
                        {
                            menu.show(row, e.getX(), e.getY());
                        }
                    }

                    @Override
                    public void mouseReleased(java.awt.event.MouseEvent e)
                    {
                        if (e.isPopupTrigger())
                        {
                            menu.show(row, e.getX(), e.getY());
                        }
                    }
                });

                content.add(row);
            }

            if (plugin.isHideZeroStatsEnabled() && hiddenStats > 0)
            {
                content.add(Box.createVerticalStrut(10));
                String hiddenText = hiddenStats == 1 ? "1 stat hidden" : hiddenStats + " stats hidden";
                JLabel hiddenLabel = new JLabel(hiddenText);
                hiddenLabel.setForeground(Color.GRAY);
                hiddenLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                content.add(hiddenLabel);
            }
        }

        revalidate();
        repaint();
    }

    public static String formatStack(int amount)
    {
        if (amount < 100_000)
        {
            return String.valueOf(amount);
        }
        else if (amount < 10_000_000)
        {
            int thousands = amount / 1_000;
            return thousands + "k";
        }
        else
        {
            double millions = amount / 1_000_000.0;

            if (amount % 1_000_000 == 0)
            {
                return String.format("%dM", (int) millions);
            }
            else
            {
                return String.format("%.1fM", millions);
            }
        }
    }
}

package com.ultimatestattracker;

import com.google.inject.Provides;
import javax.inject.Inject;

import com.ultimatestattracker.stattrackers.GoldStatTracker;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import java.awt.image.BufferedImage;

import javax.swing.SwingUtilities;

import static com.ultimatestattracker.StatKeys.*;
import com.ultimatestattracker.stattrackers.*;
import net.runelite.client.util.ImageUtil;

@PluginDependency(XpTrackerPlugin.class)
@Slf4j
@PluginDescriptor(
	name = "Ultimate Stat Tracker"
)
public class UltimateStatTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	private NavigationButton navButton;

	private UltimateStatTrackerPanel panel;

	@Inject
	private UltimateStatTrackerConfig config;

	@Inject
	private MouseManager mouseManager;

	private StatStore statStore;

	@Inject
	private ConfigManager configManager;

	@Inject
	private XpTrackerService trackerService;

	private GoldStatTracker goldStatTracker;
	private ItemStatTracker itemStatTracker;
	private MovementStatTracker movementStatTracker;
	private SkillingStatTracker skillingStatTracker;
	private FoodStatTracker foodStatTracker;
	private NPCStatTracker npcStatTracker;
	private CombatStatTracker combatStatTracker;

	@Inject
	private KeyManager keyManager;

	@Inject
	private SkillIconManager skillIconManager;

	public boolean loggedIn;
	public boolean firstLogin = true;

	public final String version = "1.1.4";
	private final String VERSION_KEY = "ustp.version";

	public boolean isPerformanceMode()
	{
		return config.performanceMode();
	}

	public boolean isHideZeroStatsEnabled()
	{
		return config.hideZeroStats();
	}

	public boolean isDynamicUpdatesEnabled()
	{
		return config.enableDynamicUpdates();
	}

	public int getDynamicUpdateRate()
	{
		return Math.max(1, config.dynamicUpdateRate());
	}

	private int dynamicUpdateTickCounter = 0;



	@Override
	protected void startUp() throws Exception
	{
		statStore = new StatStore(configManager,this, new MilestoneManager(config,client));

		goldStatTracker = new GoldStatTracker(statStore, client);
		itemStatTracker = new ItemStatTracker(statStore, client);
		movementStatTracker = new MovementStatTracker(statStore,client);
		skillingStatTracker = new SkillingStatTracker(statStore, client, trackerService);
		foodStatTracker = new FoodStatTracker(statStore, client);
		npcStatTracker = new NPCStatTracker(statStore, client);
		combatStatTracker = new CombatStatTracker(statStore, client);

		keyManager.registerKeyListener(movementStatTracker.ctrlKeyListner);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/usticon.png");

		panel = new UltimateStatTrackerPanel(this, skillIconManager);
		panel.setStatStore(statStore);

		navButton = NavigationButton.builder()
				.tooltip("Ultimate Stat Tracker")
				.icon(icon)
				.priority(5)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		keyManager.unregisterKeyListener(movementStatTracker.ctrlKeyListner);
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			for (StatKey key : ALL_KEYS)
			{
				if ("0".equals(statStore.getStatTrackingDate(key.getValue())))
				{
					String formattedDate = java.time.Instant.ofEpochMilli(System.currentTimeMillis())
							.atZone(java.time.ZoneId.systemDefault())
							.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd"));
					statStore.setStatTrackingDate(key.getValue(),formattedDate);
				}
				loggedIn = true;
			}
			if (firstLogin) {
				String lastVersion = configManager.getConfiguration("ultimatestattracker", VERSION_KEY);
				//show release notes if this is a new version
				if (!version.equals(lastVersion))
				{
					String[] lines = ReleaseNotes.getReleaseNotes().split("\\n");
					for (String line : lines)
					{
						client.addChatMessage(
								ChatMessageType.GAMEMESSAGE,
								"",
								"<col=ff0000>" + line + "</col>",
								null
						);
					}
					configManager.setConfiguration("ultimatestattracker", VERSION_KEY, version);
				}
				panel.rebuild();
				firstLogin = false;
			}
		}

	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		log.debug(event.getMenuTarget());
		log.debug(event.getMenuOption());

		itemStatTracker.onMenuOptionClicked(event);
		foodStatTracker.onMenuOptionClicked(event);
		npcStatTracker.onMenuOptionClicked(event);
		movementStatTracker.onMenuOptionClicked(event);

	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!config.performanceMode())
		{
			goldStatTracker.onWidgetLoaded(event);
			movementStatTracker.onWidgetLoaded(event);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (!config.performanceMode())
		{
			goldStatTracker.onWidgetClosed(event);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!config.performanceMode()){
			movementStatTracker.onGameTick(event);
			goldStatTracker.onGameTick(event);
			skillingStatTracker.onGameTick(event);
			itemStatTracker.onGameTick(event);
			foodStatTracker.onGameTick(event);
			npcStatTracker.onGameTick(event);
		}

		if (isDynamicUpdatesEnabled() && panel != null)
		{
			dynamicUpdateTickCounter++;
			if (dynamicUpdateTickCounter >= getDynamicUpdateRate())
			{
				dynamicUpdateTickCounter = 0;
				SwingUtilities.invokeLater(panel::rebuild);
			}
		}
		else
		{
			dynamicUpdateTickCounter = 0;
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!config.performanceMode()) {
			movementStatTracker.onAnimationChanged(event);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("UltimateStatTracker".equals(event.getGroup()) && panel != null)
		{
			dynamicUpdateTickCounter = 0;
			panel.rebuild();
		}
	}

	@Provides
	UltimateStatTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UltimateStatTrackerConfig.class);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		skillingStatTracker.onChatMessage(event);
		foodStatTracker.onChatMessage(event);
		itemStatTracker.onChatMessage(event);
		combatStatTracker.onChatMessage(event);
		movementStatTracker.onChatMessage(event);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		combatStatTracker.onHitsplatApplied(event);
	}
}

package com.ultimatestattracker.stattrackers;

import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;

import static com.ultimatestattracker.StatKeys.*;

@Slf4j
public class CombatStatTracker implements StatTracker{
    private StatStore statStore;
    private Client client;

    public CombatStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {

    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {

    }


    @Override
    public void onWidgetClosed(WidgetClosed event) {

    }

    @Override
    public void onHitsplatApplied(HitsplatApplied event)
    {
        Hitsplat hitsplat = event.getHitsplat();
        Actor actor = event.getActor();
        log.debug("Hitsplat type {}",hitsplat.getHitsplatType());
        switch(hitsplat.getHitsplatType()) {
            case HitsplatID.DAMAGE_ME: //this triggers both on damage done BY and TO the player
                if (actor == client.getLocalPlayer()) { //we took damage
                    statStore.incrementStatBy(DAMAGE_RECEIVED, hitsplat.getAmount());
                }
                else { //we did damage to something else
                    statStore.incrementStatBy(DAMAGE_DONE, hitsplat.getAmount());
                    if (statStore.getStat(BIGGEST_HITSPLAT) < hitsplat.getAmount()) {
                        statStore.setStat(BIGGEST_HITSPLAT, hitsplat.getAmount());
                    }
                }
                break;
            case HitsplatID.BLOCK_ME:
                if (actor == client.getLocalPlayer()) {
                    statStore.incrementStat(ATTACKS_BLOCKED);
                }
                else{
                    statStore.incrementStat(ATTACKS_MISSED);
                }
                break;
        }
    }

    @Override
    public void onAnimationChanged(AnimationChanged event) {

    }

    @Override
    public void onGameTick(GameTick event) {

    }

    @Override
    public void onGameStateChanged(GameStateChanged gameStateChanged) {

    }

    @Override
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.SPAM
                && event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.MESBOX)
        {
            return;
        }

        final var msg = event.getMessage();
        if (msg.contains("Oh dear, you are dead!")){
            statStore.incrementStat(DEATHS);
        }

        if (msg.contains("You resurrect a")) {
            // checking greater's first as it is most likely
            if (msg.contains("greater ghostly")) {
                statStore.incrementStat(GREATER_GHOSTS_SUMMONED);
            } else if (msg.contains("greater skeletal")) {
                statStore.incrementStat(GREATER_SKELETONS_SUMMONED);
            } else if (msg.contains("greater zombified")) {
                statStore.incrementStat(GREATER_ZOMBIES_SUMMONED);
            } else if (msg.contains("lesser ghostly")) {
                statStore.incrementStat(LESSER_GHOSTS_SUMMONED);
            } else if (msg.contains("lesser skeletal")) {
                statStore.incrementStat(LESSER_SKELETONS_SUMMONED);
            } else if (msg.contains("lesser zombified")) {
                statStore.incrementStat(LESSER_ZOMBIES_SUMMONED);
            } else if (msg.contains("superior ghostly")) {
                statStore.incrementStat(SUPERIOR_GHOSTS_SUMMONED);
            } else if (msg.contains("superior skeletal")) {
                statStore.incrementStat(SUPERIOR_SKELETONS_SUMMONED);
            } else if (msg.contains("superior zombified")) {
                statStore.incrementStat(SUPERIOR_ZOMBIES_SUMMONED);
            }
        }
    }
}

package com.ultimatestattracker.stattrackers;

import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.util.Text;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import static com.ultimatestattracker.StatKeys.*;

@Slf4j
public class FoodStatTracker implements StatTracker{
    private StatStore statStore;
    private Client client;
    private String lastThingConsumed;
    private int lastHp = -1;

    // Maps OSRS chat food names (lowercase, with spaces as shown in-game) to the
    // specific stat key that should be incremented when that food is eaten.
    // Falls back to existing FOOD_EATEN which is incremented for every food.
    private static final Map<String, String> FOOD_EATEN_MAP = new HashMap<>();
    static {
        // Non-fish foods (already supported)
        FOOD_EATEN_MAP.put("cabbage", CABBAGE_EATEN);
        FOOD_EATEN_MAP.put("trout", TROUT_EATEN);
        // Main OSRS fish that can be eaten
        FOOD_EATEN_MAP.put("shrimp", SHRIMP_EATEN);
        FOOD_EATEN_MAP.put("anchovies", ANCHOVIES_EATEN);
        FOOD_EATEN_MAP.put("sardine", SARDINE_EATEN);
        FOOD_EATEN_MAP.put("herring", HERRING_EATEN);
        FOOD_EATEN_MAP.put("pike", PIKE_EATEN);
        FOOD_EATEN_MAP.put("cod", COD_EATEN);
        FOOD_EATEN_MAP.put("salmon", SALMON_EATEN);
        FOOD_EATEN_MAP.put("tuna", TUNA_EATEN);
        FOOD_EATEN_MAP.put("bass", BASS_EATEN);
        FOOD_EATEN_MAP.put("lobster", LOBSTER_EATEN);
        FOOD_EATEN_MAP.put("swordfish", SWORDFISH_EATEN);
        FOOD_EATEN_MAP.put("monkfish", MONKFISH_EATEN);
        FOOD_EATEN_MAP.put("shark", SHARK_EATEN);
        FOOD_EATEN_MAP.put("manta ray", MANTA_RAY_EATEN);
        FOOD_EATEN_MAP.put("anglerfish", ANGLERFISH_EATEN);
        FOOD_EATEN_MAP.put("karambwan", KARAMBWAN_EATEN);
        FOOD_EATEN_MAP.put("dark crab", DARK_CRAB_EATEN);
        FOOD_EATEN_MAP.put("sea turtle", SEA_TURTLE_EATEN);
        // Deep Sea Trawling fish
        FOOD_EATEN_MAP.put("haddock", HADDOCK_EATEN);
        FOOD_EATEN_MAP.put("giant krill", GIANT_KRILL_EATEN);
        FOOD_EATEN_MAP.put("yellowfin", YELLOWFIN_EATEN);
        FOOD_EATEN_MAP.put("halibut", HALIBUT_EATEN);
        FOOD_EATEN_MAP.put("bluefin", BLUEFIN_EATEN);
        FOOD_EATEN_MAP.put("marlin", MARLIN_EATEN);
        // Hunter minigame fish
        FOOD_EATEN_MAP.put("dashing kebbit", DASHING_KEBBIT_EATEN);
        FOOD_EATEN_MAP.put("sunlight antelope", SUNLIGHT_ANTELOPE_EATEN);
        FOOD_EATEN_MAP.put("moonlight antelope", MOONLIGHT_ANTELOPE_EATEN);
        FOOD_EATEN_MAP.put("pyre fox", PYRE_FOX_EATEN);
    }


    private String[] oneHPFood = {
            "Anchovies",
            "Chopped onion",
            "Asgarnian ale",
            "Wizard's mind bomb",
            "Greenman's ale",
            "Dragon bitter",
            "Dwarven stout",
            "Beer",
            "Potato",
            "Onion",
            "Cabbage",
            "Equa leaves",
            "Pot of cream",
            "Nettle-water",
            "Bandit's brew",
            "Axeman's folly",
            "Chef's delight",
            "Slayer's respite",
            "Cider",
            "Fresh monkfish",
            "Elven dawn",
            "Kovac's grog"
    };

    public FoodStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (Objects.equals(event.getMenuOption(), "Eat"))
        {
            lastThingConsumed = Text.removeTags(event.getMenuTarget());
        }
        else if (Objects.equals(event.getMenuOption(), "Drink")) {
            lastThingConsumed = event.getMenuTarget();
        }

    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {

    }

    @Override
    public void onWidgetClosed(WidgetClosed event) {

    }

    @Override
    public void onGameTick(GameTick event) {

        //check if hp changed
        //if did by 1 and last thing consumed was not a one hp food then natural health regen +1
        int currentHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
        if (lastHp != -1 && currentHp == lastHp + 1) {
            //then if we didnt eat a 1 hp food most recently, this was probably natural regen
            //note if someone were to eat a more than 1 hp food at 98 and go to 99 (or any time they are 1 hp below their cap)
            //this would mistakenly be counted as regen
            //however i dont really think thats a huge problem as that should be rathar rare
            //maybe todo to improve this to have better food tracking and thus be more accurate
            if (lastThingConsumed == null) {
                statStore.incrementStat(HP_REGEN);
            } else if (Arrays.stream(oneHPFood).noneMatch(food -> Text.removeTags(lastThingConsumed).contains(food))) {
                statStore.incrementStat(HP_REGEN);
            } else
            {
                // If the last thingConsumed is not cleared or changed, and it was a 1 hp regen item, then hp regen stops tracking.
                // With this clear at most 1 hp regen is lost per "eat" of these items.
                lastThingConsumed = null;
            }
        }

        lastHp = currentHp;

    }

    @Override
    public void onGameStateChanged(GameStateChanged gameStateChanged) {

    }

    @Override
    public void onChatMessage(ChatMessage event) {

        if (event.getType() != ChatMessageType.SPAM
                && event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.MESBOX)
        {
            return;
        }

        String msg = event.getMessage();
        // Cake has 3 different chat message formats for its 3 slices, which we
        // track in CAKE_SLICES_EATEN. Compute once and reuse below.
        boolean isCakeSlice = msg.contains("part of the cake.")
                || msg.contains("some more of the cake.")
                || msg.contains("slice of cake");

        // Bump the generic FOOD_EATEN counter for any eating event, including the
        // "part of"/"some more of" cake variants that don't fit the "You eat the X." pattern below.
        if (msg.contains("You eat the") || isCakeSlice) {
            statStore.incrementStat(FOOD_EATEN);
        }

        if (msg.contains("You eat the")){
            //get the food name from the message, which is from the first space after "you eat the"
            //to the first period
            String foodName = msg
                    .substring(msg.indexOf("the ") + "the ".length(),msg.indexOf(".")).trim();

            String lookup = foodName.toLowerCase();
            if (lookup.endsWith(" meat")) {
                lookup = lookup.substring(0, lookup.length() - " meat".length());
            }
            log.debug("Suspected food name is {}", lookup);
            // Increment a specific fish/food counter if this food is known
            String matchingStat = FOOD_EATEN_MAP.get(lookup);
            if (matchingStat != null) {
                statStore.incrementStat(matchingStat);
            }
        }

        if (isCakeSlice) {
            log.debug("Detected cake slice eaten: {}", msg);
            statStore.incrementStat(CAKE_SLICES_EATEN);
        }

        //for drinks it says "you drink the <x>"
        //for potions it says "you drink some of the <x>"
        else if (event.getMessage().contains("You drink")){
            //food name in this case is everything from "the" to the first period.
            String foodName = event.getMessage()
                    .substring(event.getMessage().indexOf("the ") + "the ".length(),event.getMessage().indexOf(".")).trim(); //todo bad repeated code ugly

            log.debug("Suspected food name is {}",foodName);
            if (foodName.equals("beer")){
                statStore.incrementStat(BEER_DRANK);
            }

            if (event.getMessage().contains(("You drink some of the")) || event.getMessage().contains(("You drink some of your"))){
                statStore.incrementStat(POTION_SIPS_DRANK);

                if (event.getMessage().contains("divine")) {
                    statStore.incrementStatBy(DIVINE_DAMAGE, 10); // Divine pots always do 10 damage
                }
            }
        }

        if(event.getMessage().contains("You quickly smash the empty vial")){
            statStore.incrementStat(VIALS_SMASHED);
        }
    }

    @Override
    public void onHitsplatApplied(HitsplatApplied event) {

    }

    @Override
    public void onAnimationChanged(AnimationChanged event) {

    }
}

package com.ultimatestattracker.stattrackers;


import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.events.*;
import net.runelite.api.widgets.WidgetInfo;
import net.runelite.api.widgets.InterfaceID;

import static com.ultimatestattracker.StatKeys.SHOP_GP_GAINED;
import static com.ultimatestattracker.StatKeys.SHOP_GP_SPENT;

/**
 *  Handles All stat tracking logic for gold related stats
 */
@Slf4j
public class GoldStatTracker implements StatTracker {
    private StatStore statStore;
    private Client client;
    private boolean shopOpen = false;
    private int lastShopGold = -1;

    public GoldStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {

    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {
        //log.debug(String.valueOf(event.getGroupId()));
        //shop spent at gp tracking
        if (event.getGroupId() == InterfaceID.SHOP_INVENTORY)
        {
            shopOpen = true;
            lastShopGold = client.getItemContainer(InventoryID.INVENTORY).count(ItemID.COINS_995);
            log.debug("Shop opened, starting GP tracking. Current gold: {}", lastShopGold);
        }
    }

    @Override
    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == InterfaceID.SHOP_INVENTORY)
        {
            shopOpen = false;
            lastShopGold = -1;
            log.debug("Shop closed, stopping GP tracking.");
        }
    }

    @Override
    public void onGameTick(GameTick event) {
        if (shopOpen) {
            ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
            if (inv == null) {
                log.debug("Inventory is null, cannot track GP");
                return;
            }

            int currentGold = inv.count(ItemID.COINS_995);
            if (lastShopGold == -1) {
                lastShopGold = currentGold;
                return;
            }

            if (currentGold < lastShopGold) {
                int spent = lastShopGold - currentGold;
                statStore.incrementStatBy(SHOP_GP_SPENT, spent);
                //log.debug("Spent {} gp, total: {}", spent, statStore.getStat(SHOP_GP_SPENT));
            } else if (currentGold > lastShopGold) {
                int gained = currentGold - lastShopGold;
                statStore.incrementStatBy(SHOP_GP_GAINED, gained);
                //log.debug("Gained {} gp, total: {}", gained, statStore.getStat(SHOP_GP_GAINED));
            }

            lastShopGold = currentGold;
        }
    }

    @Override
    public void onGameStateChanged(GameStateChanged gameStateChanged) {

    }

    @Override
    public void onChatMessage(ChatMessage event) {

    }

    @Override
    public void onHitsplatApplied(HitsplatApplied event) {

    }

    @Override
    public void onAnimationChanged(AnimationChanged event) {

    }
}

package com.ultimatestattracker.stattrackers;

import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.events.*;
import net.runelite.client.util.Text;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import static com.ultimatestattracker.StatKeys.*;

@Slf4j
public class ItemStatTracker implements StatTracker{
    private StatStore statStore;
    private Client client;

    // Maps the canonical (lower-case, no "grimy " prefix) herb name as it appears
    // in OSRS chat messages to the per-herb placed stat key. Used to track
    // grimy and clean variants of the same herb under a single counter.
    private static final Map<String, String> HERB_NAME_TO_STAT = new HashMap<>();
    static {
        HERB_NAME_TO_STAT.put("guam leaf", GUAM_LEAF_PLACED);
        HERB_NAME_TO_STAT.put("marrentill", MARRENTILL_PLACED);
        HERB_NAME_TO_STAT.put("tarromin", TARROMIN_PLACED);
        HERB_NAME_TO_STAT.put("harralander", HARRALANDER_PLACED);
        HERB_NAME_TO_STAT.put("ranarr weed", RANARR_WEED_PLACED);
        HERB_NAME_TO_STAT.put("toadflax", TOADFLAX_PLACED);
        HERB_NAME_TO_STAT.put("irit leaf", IRIT_LEAF_PLACED);
        HERB_NAME_TO_STAT.put("avantoe", AVANTOE_PLACED);
        HERB_NAME_TO_STAT.put("kwuarm", KWUARM_PLACED);
        HERB_NAME_TO_STAT.put("huasca", HUASCA_PLACED);
        HERB_NAME_TO_STAT.put("snapdragon", SNAPDRAGON_PLACED);
        HERB_NAME_TO_STAT.put("cadantine", CADANTINE_PLACED);
        HERB_NAME_TO_STAT.put("lantadyme", LANTADYME_PLACED);
        HERB_NAME_TO_STAT.put("dwarf weed", DWARF_WEED_PLACED);
        HERB_NAME_TO_STAT.put("torstol", TORSTOL_PLACED);
    }


    public ItemStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (Objects.equals(event.getMenuOption(), "Examine"))
        {
            statStore.incrementStat(EXAMINE);
            log.debug("Item examine clicked: {}", event.getMenuTarget());
        }
        else if (Objects.equals(event.getMenuOption(), "Drop"))
        {
            statStore.incrementStat(ITEMS_DROPPED);
            log.debug("Item drop clicked: {}", event.getMenuTarget());
        }
    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {

    }

    @Override
    public void onWidgetClosed(WidgetClosed event) {

    }

    @Override
    public void onGameTick(GameTick event) {
    }

    @Override
    public void onGameStateChanged(GameStateChanged gameStateChanged) {

    }

    @Override
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.SPAM
                && event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.MESBOX)
        {
            return;
        }

        String msg = event.getMessage();
        if (msg.contains(("You pick a"))|| msg.contains("You pick some")){
            //item name is last space to first period
            String itemName = msg.substring(msg.lastIndexOf(" ") + 1, msg.indexOf("."));
            log.debug("suspected picked item name is {}", itemName);
            if (itemName.equals("cabbage")){
                statStore.incrementStat(CABBAGE_PICKED);
                log.debug("Cabbage picked message: {}", msg);
            }
            else if (itemName.equals("flax")){
                statStore.incrementStat(FLAX_PICKED);
                log.debug("Flax picked message: {}", msg);
            }
        }
        else if (msg.contains("You scatter the")){
            statStore.incrementStat(ASHES_SCATTERED);
        }
        else if (msg.contains("into your herb sack")){
            statStore.incrementStat(HERBS_PLACED_IN_HERB_SACK);
            log.debug("Herb placed in herb sack: {}", msg);

            // Extract the herb name from the message:
            //   "You put the <herb name> herb into your herb sack."
            // The herb name appears after "the " and before the first " herb".
            // It may optionally be prefixed with "grimy " (e.g. "grimy ranarr weed")
            // — strip that prefix so grimy and clean herbs share a counter.
            int herbStart = msg.indexOf("the ") + "the ".length();
            int herbEnd = msg.indexOf(" herb", herbStart);
            if (herbEnd > herbStart) {
                String herbName = msg.substring(herbStart, herbEnd).trim().toLowerCase();
                if (herbName.startsWith("grimy ")) {
                    herbName = herbName.substring("grimy ".length());
                }
                String herbStat = HERB_NAME_TO_STAT.get(herbName);
                if (herbStat != null) {
                    statStore.incrementStat(herbStat);
                } else {
                    log.debug("Unknown herb name parsed from message: {}", herbName);
                }
            }
        }
    }

    @Override
    public void onHitsplatApplied(HitsplatApplied event) {

    }

    @Override
    public void onAnimationChanged(AnimationChanged event) {

    }
}

package com.ultimatestattracker.stattrackers;

import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.KeyListener;
import net.runelite.api.Varbits;
import net.runelite.client.util.Text;

import java.awt.event.KeyEvent;

import static com.ultimatestattracker.StatKeys.*;

@Slf4j
public class MovementStatTracker implements StatTracker{
    private StatStore statStore;
    private Client client;
    private WorldPoint lastPlayerPos = null;

    private int runEnergyIconId = 10485793;
    private int runEnergyDisabledSpriteId = 1069;
    private int runEnergyEnabledSpriteId = 1070;
    private Widget runEnergyWidget = null;

    private boolean ctrlHeld = false;
    private String lastOptionClicked;

    public MovementStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    public final KeyListener ctrlKeyListner = new KeyListener()
    {
        @Override
        public void keyTyped(KeyEvent e) { }

        @Override
        public void keyPressed(KeyEvent e)
        {
            if(e.getKeyCode() == KeyEvent.VK_CONTROL){
                ctrlHeld = true;
            }
        }

        @Override
        public void keyReleased(KeyEvent e)
        {
            if(e.getKeyCode() == KeyEvent.VK_CONTROL){
                ctrlHeld = false;
            }
        }
    };

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {
        //have to handle diary teleports carefully
        if (event.getMenuTarget().toLowerCase().contains("teleport") &&
                (! (event.getMenuOption().toLowerCase().contains("grand exchange")||
                        event.getMenuOption().toLowerCase().contains("yanille") ||
                        event.getMenuOption().toLowerCase().contains("seers'")))){

                lastOptionClicked =Text.removeTags(event.getMenuTarget()).toLowerCase();
        }
        else {
            lastOptionClicked = event.getMenuOption().toLowerCase();
        }
    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == 193){
            log.debug("potential spirit tree popup");
            Widget chatBoxMessage = client.getWidget(193,2);
            if (chatBoxMessage == null){
                log.debug("couldnt find chatbox message widget for spirit tree");
            }
            if (chatBoxMessage!=null){
                log.debug("text: {}", chatBoxMessage.getText());
                if (chatBoxMessage.getText().contains("place your hands on the dry")){
                    statStore.incrementStat(SPIRIT_TREE_TELES);
                }
            }
        }
    }

    @Override
    public void onWidgetClosed(WidgetClosed event) {

    }

    //todo add key listener for ctrl, if held down, then player will walk.
    //maybe just use animations
    @Override
    public void onGameTick(GameTick event) {
        Player local = client.getLocalPlayer();
        if (local != null) {
            WorldPoint currentPos = local.getWorldLocation();
            if (lastPlayerPos != null) {
                int dx = Math.abs(currentPos.getX() - lastPlayerPos.getX());
                int dy = Math.abs(currentPos.getY() - lastPlayerPos.getY());
                int maxMove = Math.max(dx, dy);

                if (maxMove > 0 && maxMove < 3) {
                    runEnergyWidget = client.getWidget(runEnergyIconId);
                    boolean runEnabled = false;
                    if (runEnergyWidget != null && !runEnergyWidget.isHidden())
                    {
                        int spriteId = runEnergyWidget.getSpriteId();
                        runEnabled = spriteId == runEnergyEnabledSpriteId;
                    }

                    //todo in future add config setting if ctrl to inverse isnt enabled
                    if ( (runEnabled && !ctrlHeld) || (!runEnabled && ctrlHeld)){
                        statStore.incrementStatBy(TILES_RAN, maxMove);
                    }
                    else{
                        statStore.incrementStatBy(TILES_WALKED, maxMove);
                    }

                    //log.debug("Moved {} tiles (ran {})", maxMove, runEnabled);
                }
            }
            lastPlayerPos = currentPos;
        }
    }

    @Override
    public void onGameStateChanged(GameStateChanged gameStateChanged) {

    }

    @Override
    public void onChatMessage(ChatMessage event) {

    }

    @Override
    public void onHitsplatApplied(HitsplatApplied event) {

    }

    @Override public void onAnimationChanged(AnimationChanged event)
    {
        Actor actor = event.getActor();
        if (actor == client.getLocalPlayer()) {     
            //todo export to constants
            if (actor.getAnimation() == 3265 ){
                statStore.incrementStat(FAIRY_RING_TELES);
            }

            //tele tab
            else if (actor.getAnimation() == 4069){
                trackTeleTab(lastOptionClicked);
            }

            //standard teleport
            else if(actor.getAnimation() == 714){
                trackStandardTeleport(lastOptionClicked);
            }
        }
    }

    private void trackStandardTeleport(String lastOptionClicked) {
        trackTeleport(lastOptionClicked);
    }

    private void trackTeleTab(String lastOptionClicked) {
        trackTeleport(lastOptionClicked);
    }

    private void trackTeleport(String lastOptionClicked) {
        statStore.incrementStat(TOTAL_TELEPORTS);
        //use if else instead of switch here because for non diary teles we get <x> teleport, but for diary teles we just get <x> so we need to use contains
        log.debug("last teleport clicked {}",lastOptionClicked);
        if (lastOptionClicked.contains("varrock")){
            statStore.incrementStat(VARROCK_TELEPORT);
        }
        else if (lastOptionClicked.contains("grand exchange")){
            statStore.incrementStat(GRAND_EXCHANGE_TELEPORT);
        }
        else if (lastOptionClicked.contains("lumbridge")){
            statStore.incrementStat(LUMBRIDGE_TELEPORT);
        }
        else if (lastOptionClicked.contains("falador")){
            statStore.incrementStat(FALADOR_TELEPORT);
        }
        else if (lastOptionClicked.contains("camelot")){
            statStore.incrementStat(CAMELOT_TELEPORT);
        }
        else if (lastOptionClicked.contains("seers'")){
            statStore.incrementStat(SEERS_VILLAGE_TELEPORT);
        }
        else if (lastOptionClicked.contains("ardougne")){
            statStore.incrementStat(ARDOUGNE_TELEPORT);
        }
        else if (lastOptionClicked.contains("kourend")){
            statStore.incrementStat(KOUREND_TELEPORT);
        }
        else if (lastOptionClicked.contains("civitas")){
            statStore.incrementStat(FORTIS_TELEPORT);
        }
        else if (lastOptionClicked.contains("watchtower")){
           statStore.incrementStat(WATCHTOWER_TELEPORT);
        }
        else if (lastOptionClicked.contains("yanille")){
            statStore.incrementStat(YANILLE_TELEPORT);
        }
        else if (lastOptionClicked.contains("trollheim")){
            statStore.incrementStat(TROLLHEIM_TELEPORT);
        }
        else if (lastOptionClicked.contains("ape atoll")){
            statStore.incrementStat(APE_ATOLL_TELEPORT);
        }
        else if (lastOptionClicked.contains("house")){
            statStore.incrementStat(HOUSE_TELEPORT);
        }


    }
}

package com.ultimatestattracker.stattrackers;

import com.ultimatestattracker.StatStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.*;

import java.util.Objects;

import static com.ultimatestattracker.StatKeys.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Player;

@Slf4j
public class NPCStatTracker implements StatTracker{
    private StatStore statStore;
    private Client client;

    boolean evenTick = false;

    boolean pendingPet = false;

    private static final WorldPoint AREA_NE = new WorldPoint(2663, 3244, 0);
    private static final WorldPoint AREA_SW = new WorldPoint(2628, 3223, 0);

    private static final String TARGET_NPC_NAME = "'The Guns'";


    public NPCStatTracker(StatStore statStore, Client client)
    {
        this.statStore = statStore;
        this.client = client;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (Objects.equals(event.getMenuOption(), "Pet"))
        {
            pendingPet = true;
        }
    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {

    }

    @Override
    public void onWidgetClosed(WidgetClosed event) {

    }

    @Override
    public void onGameTick(GameTick event) {
        if (pendingPet && evenTick){ //2 tick limited since petting is 2 tick limited
            statStore.incrementStat(CRITTERS_PET);
            pendingPet = false;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
        {
            return;
        }
        WorldPoint playerLocation = localPlayer.getWorldLocation();
        if ((isInArea(playerLocation)))
        {
            //try to find "The Guns"
            for (NPC npc : client.getNpcs()) {
                if (npc == null || npc.getName() == null) {
                    continue;
                }

                if (!npc.getName().equalsIgnoreCase(TARGET_NPC_NAME)) {
                    continue;
                }

                String overhead = npc.getOverheadText();

                if (overhead == null) {
                    continue;
                }

                //log.debug("Guns: {}", overhead);
                String digits = overhead.replaceAll("[^0-9]", "");
                if (digits.isEmpty())
                {
                    return;
                }
                int value = Integer.parseInt(digits);
                if (statStore.getStat(THE_GUNS) < value ) {
                    //new highest number seen counted
                    statStore.setStat(THE_GUNS, value);
                }
            }
        }
        evenTick = !evenTick;
    }

    private boolean isInArea(WorldPoint point)
    {
        return point.getX() >= AREA_SW.getX()
                && point.getX() <= AREA_NE.getX()
                && point.getY() >= AREA_SW.getY()
                && point.getY() <= AREA_NE.getY()
                && point.getPlane() == AREA_SW.getPlane();
    }

